import React from "react";
import { Link } from "react-router-dom";
import "./Navbar.css";

function Navbar({ setToken }) {
  const handleLogout = () => {
    localStorage.removeItem("token");
    setToken(null);
  };

  return (
    <nav className="navbar">
      <div className="navbar-left">
        <Link to="/risks" className="navbar-link">Risks</Link>
        <Link to="/newrisk" className="navbar-link">New Risk</Link>
        <Link to="/auditlogs" className="navbar-link">Audit Logs</Link>
      </div>
      <div>
        <button onClick={handleLogout} className="logout-btn">
          Logout
        </button>
      </div>
    </nav>
  );
}

export default Navbar;
